import javax.imageio.ImageIO; import java.awt.image.BufferedImage; import java.io.File;
public class PixStats { public static void main(String[] a) throws Exception { BufferedImage p = ImageIO.read(new File(a[0])), q = ImageIO.read(new File(a[1])); int n=0,b8=0,b32=0,max=0; long sum=0; for (int y=0;y<p.getHeight();y++) for (int x=0;x<p.getWidth();x++){ int c=p.getRGB(x,y), d=q.getRGB(x,y); int m=0; for(int s=0;s<24;s+=8) m=Math.max(m,Math.abs(((c>>s)&255)-((d>>s)&255))); if(m>0){n++;sum+=m;} if(m>8)b8++; if(m>32)b32++; max=Math.max(max,m);} System.out.printf("%-48s differing %6d  >8: %5d  >32: %4d  max %3d  mean %.1f%n", a[2], n, b8, b32, max, n==0?0:(double)sum/n); } }
